#!/usr/bin/env python3
import argparse, datetime, hashlib, json, pathlib, re, subprocess, time

ROOT = pathlib.Path('/repos/Antigravity/typst-crystalline')
OUT = ROOT / '00_nucleo/diagnosticos'
MAPS = ['cividis','coolwarm','crest','flare','icefire','mako','rainbow','rocket','turbo','vlag','viridis','inferno','magma','plasma','spectral']
PROFILES = {'default': [], 'html':['--features','html'], 'a11y':['--features','a11y-extras'], 'html+a11y':['--features','html,a11y-extras']}
OWNER_FILES = ['compiler/eval/repr.md','entities/module.md','compiler/stdlib/color.md','compiler/stdlib/loading.md','compiler/eval.md','compiler/eval/tests.md','compiler/stdlib/_comum.md','compiler/stdlib/plugin.md']
WASM = 'plugin(bytes((0,97,115,109,1,0,0,0,5,3,1,0,1,7,10,1,6,109,101,109,111,114,121,2,0)))'
def sha(b): return hashlib.sha256(b).hexdigest()
def stamp(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def command(argv):
    t=time.monotonic_ns(); at=stamp()
    try:
        r=subprocess.run(argv,cwd=ROOT,capture_output=True,timeout=30)
        d=dict(argv=argv,exit_code=r.returncode,stdout=r.stdout.decode('utf-8'),stderr=r.stderr.decode('utf-8'),stdout_sha256=sha(r.stdout),stderr_sha256=sha(r.stderr),duration_ns=time.monotonic_ns()-t,timestamp=at,state='COMPLETE')
        if r.returncode==0:
            try: d['value']=json.loads(d['stdout'])
            except ValueError: d.update(state='Unknown',reason_code='PARSER_UNSUPPORTED')
        elif r.returncode not in (1,2): d.update(state='Unknown',reason_code='PROCESS_EXIT')
        return d
    except (subprocess.TimeoutExpired,UnicodeDecodeError) as e:
        return dict(argv=argv,state='Unknown',reason_code=type(e).__name__,duration_ns=time.monotonic_ns()-t,timestamp=at,error=str(e))
def run(binary, expression, profile='default', fixture=False):
    argv=[binary,'eval',expression,'--format','json']+PROFILES[profile]
    if fixture: argv += ['--root','/tmp','--in','/tmp/p1304_empty.typ']
    return command(argv)
def probe(id, expression, fixture=False): return dict(id=id,expression=expression,fixture=fixture)
def d_suite():
    p=[]
    for name in ['std','color.map','calc','sym','pdf']:
        p.append(probe('module/'+name,'(kind: repr(type('+name+')), repr: repr('+name+'))'))
        p.append(probe('module-name-diagnostic/'+name,name+'.p1304_absent'))
    p.append(probe('module/imported-named','{ import "/p1304_named.typ" as m; (kind: repr(type(m)), repr: repr(m), x: m.x) }',True))
    p.append(probe('module/imported-name-diagnostic','{ import "/p1304_named.typ" as m; m.p1304_absent }',True))
    p.append(probe('module/anonymous-plugin','{ let m = '+WASM+'; (kind: repr(type(m)), repr: repr(m)) }'))
    p.append(probe('module/anonymous-name-diagnostic','{ let m = '+WASM+'; m.p1304_absent }'))
    for name in MAPS:
        x='color.map.'+name
        p.append(probe('map/'+name,'(kind: repr(type('+x+')), n: '+x+'.len(), rgba: '+x+'.map(c => c.components().map(x => float(x))), hex: '+x+'.map(c => c.to-hex()), repr: repr('+x+'))'))
    for n in [0,1,39,40,41,42,81]:
        p.append(probe('repr-array-boundary/'+str(n),'repr(range('+str(n)+'))'))
    p.append(probe('repr-array-boundary/nested','repr((range(41), (0,)))'))
    return p
def e_suite():
    p=[]
    inputs={
        'ordered-dict':'(z: 3, a: 1, m: 2)', 'array':'(3, 1, 2)', 'none':'none', 'bool':'true', 'int':'-17', 'float':'1.25',
        'escaping':r'"quote\" slash\\ tab\t newline\n unicode ç λ"',
        'nesting':'(z: (b: (1, 2), a: true), a: ((x: 1), (x: 2)))',
        'multiline':r'"first\nsecond\nthird\n"',
        'opaque-public-repr':'rgb(1, 2, 3)', 'empty-dict':'(:)', 'empty-array':'()',
    }
    for fmt in ['json','toml','yaml']:
        path=fmt+'.encode'
        p.append(probe(path+'/presence-kind-repr','(kind: repr(type('+path+')), repr: repr('+path+'))'))
        p.append(probe(path+'/opaque-reference','repr(rgb(1, 2, 3))'))
        for key,value in inputs.items():
            # TOML top-level values must be dicts; record rejection too below.
            arg='(value: '+value+')' if fmt=='toml' and key not in ['ordered-dict','nesting','empty-dict'] else value
            for pretty in (['default','true','false'] if fmt!='yaml' else ['default']):
                suffix='' if pretty=='default' else ', pretty: '+pretty
                p.append(probe(path+'/'+key+'/'+pretty,path+'('+arg+suffix+')'))
        errors={'missing':'', 'extra':'(a: 1), 2','unexpected-named':'(a: 1), p1304: true','positional-as-named':'value: (a: 1)'}
        if fmt!='yaml': errors['wrong-pretty-type']='(a: 1), pretty: 1'
        else: errors['unsupported-pretty']='(a: 1), pretty: true'
        if fmt=='toml':
            for key,value in inputs.items():
                if key not in ['ordered-dict','nesting','empty-dict']: errors['non-dict-'+key]=value
        for key,args in errors.items(): p.append(probe(path+'/error/'+key,path+'('+args+')'))
    return p
def inputs_metadata():
    owners=[]
    for rel in OWNER_FILES:
        path=ROOT/'00_nucleo/prompts'/rel; b=path.read_bytes(); content=b.decode()
        owner=re.search(r'`(01_core/[^`]+\.rs)`',content)
        owners.append(dict(path=str(path.relative_to(ROOT)),sha256=sha(b),declared_code_hash=re.search(r'Hash do Código: (\w+)',content).group(1),consumer=owner.group(1) if owner else None,read_integrally=True))
    paths=['01_core/src/compiler/eval/repr.rs','01_core/src/entities/module.rs','01_core/src/compiler/stdlib/color.rs','01_core/src/compiler/stdlib/loading.rs','01_core/src/compiler/eval/mod.rs','01_core/src/compiler/eval/tests.rs','01_core/src/compiler/stdlib/mod.rs','01_core/src/compiler/stdlib/plugin.rs','01_core/src/compiler/eval/modules.rs','lab/typst-original/crates/typst-library/src/foundations/module.rs','lab/typst-original/crates/typst-library/src/foundations/array.rs','lab/typst-original/crates/typst-library/src/foundations/value.rs','lab/typst-original/crates/typst-library/src/foundations/plugin.rs','lab/typst-original/crates/typst-library/src/loading/json.rs','lab/typst-original/crates/typst-library/src/loading/toml.rs','lab/typst-original/crates/typst-library/src/loading/yaml.rs','lab/typst-original/crates/typst-library/src/visualize/color.rs']
    return dict(owners=owners,sources=[dict(path=p,sha256=sha((ROOT/p).read_bytes())) for p in paths])
def state():
    return {label:subprocess.check_output(argv,cwd=ROOT,text=True) for label,argv in [('head',['git','rev-parse','HEAD']),('diff_stat',['git','diff','HEAD','--stat']),('status',['git','status','--short']),('staged_stat',['git','diff','--cached','--stat'])]}
def measure(binary,side):
    result=dict(binary=dict(path=binary,sha256=sha(pathlib.Path(binary).read_bytes())),side=side,timestamp=stamp(),source_state=state(),inputs=inputs_metadata(),D=[],E=[])
    for phase,suite in [('D',d_suite()),('E',e_suite())]:
        for p in suite:
            row=dict(p,profiles={})
            for profile in PROFILES: row['profiles'][profile]=run(binary,p['expression'],profile,p['fixture'])
            result[phase].append(row)
        print(side,phase,len(suite),'probes',flush=True)
    return result
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--binary',required=True);ap.add_argument('--side',required=True);ap.add_argument('--output',required=True);args=ap.parse_args()
    result=measure(args.binary,args.side)
    result['script_source']=pathlib.Path(__file__).read_text();result['script_sha256']=sha(result['script_source'].encode())
    pathlib.Path(args.output).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__': main()
